const form = document.querySelector('#note-form');
const input = document.querySelector('#note-text');
const list = document.querySelector('#notes-list');
const count = document.querySelector('#note-count');
const emptyState = document.querySelector('#empty-state');
const clearButton = document.querySelector('#clear-all');
const clearDialog = document.querySelector('#clear-dialog');

function updateBoard() {
  const total = list.children.length;
  count.textContent = String(total);
  emptyState.hidden = total > 0;
  clearButton.disabled = total === 0;
}

function makeNote(text, color) {
  const item = document.createElement('li');
  item.className = `note note-${color}`;
  const editor = document.createElement('textarea');
  editor.className = 'note-text';
  editor.setAttribute('aria-label', 'Edit note');
  editor.maxLength = 500;
  editor.value = text;
  const actions = document.createElement('div');
  actions.className = 'note-actions';
  const deleteButton = document.createElement('button');
  deleteButton.type = 'button';
  deleteButton.className = 'delete-button';
  deleteButton.textContent = 'Delete';
  deleteButton.setAttribute('aria-label', 'Delete note');
  deleteButton.addEventListener('click', () => {
    item.remove();
    updateBoard();
  });
  actions.append(deleteButton);
  item.append(editor, actions);
  list.prepend(item);
  updateBoard();
  editor.focus();
}

form.addEventListener('submit', event => {
  event.preventDefault();
  const text = input.value.trim();
  if (!text) {
    input.focus();
    return;
  }
  const color = form.querySelector('input[name="color"]:checked').value;
  makeNote(text, color);
  input.value = '';
  input.focus();
});

clearButton.addEventListener('click', () => {
  if (list.children.length) clearDialog.showModal();
});

document.querySelector('#confirm-clear').addEventListener('click', () => {
  list.replaceChildren();
  updateBoard();
  clearButton.focus();
});

updateBoard();
